m=Machine(9,['https://nana-press.com/kaiseki/machine/465/12693/','https://nana-press.com/kaiseki/machine/465/12706/','https://1geki.jp/slot/s_hey_eskagami/0/'],[
 '初当りはボーナス＋AT直撃の公表合算。引き戻しはDCA失敗後の別機会で、直撃と混ぜない。',
 '共通ベルは通常左第1停止、ボーナス・AT中はナビなしベル。その他の役の設定共通値も保持。',
 'トランクCZ、通常ハズレ直撃、引き戻し、内部状態別レア役ボーナス、リセット後条件付きモードを確認。',
 '終了画面は4テーブルを限定転記。継続で繰返す画面と教会を新抽選から除く。',
 '66Gボーナスと単回44/55/66G上乗せを確定条件に、70G・教会を設定示唆から分離。',
 '当日Gにはボーナス・ATを含む。7000G特殊テーブルは一度だけで、以後は5001G表に戻る。設定3・Lは数値仮説に追加しない。'])
g='kagami_initial_path'
m.ratio('初当り合算',[273.1,263.5,229.8,200.6,189.6],'NORMAL_GAME_TRIAL','通常ゲーム数とボーナス・AT直撃を含む初当りの合計を数えます。引き戻しゾーン内のATは含めません。',group=g)
m.ratio('共通ベル',[34,33.5,33,32.5,32],'TOTAL_GAME_TRIAL','通常時は左第1停止のベル、ボーナス・AT中はナビなしベルを数えます。対応する通常・ボーナス・ATの全対象Gを母数とし、ナビありベルは数えません。')
m.num('通常時ハズレのAT直撃',['1/'+str(v) for v in [7576.4,5842.6,3700.9,2455.1,1985.4]],'NORMAL_MISS_TRIAL','通常時ハズレ成立の対象試行と直撃を記録します。資料の抽選条件を保持し、通常Gへの等価換算は主張しません。引き戻しやDCAの復帰を直撃にしません。',kind='conditional_probability',group=g,s=3)
m.pct('AT終了後の引き戻し',[10.2,10.2,15.2,19.9,26.2],'DCA_FAILED_AT_END_TRIAL','ドリームカムズアゲイン失敗後の対象終了を母数に、その後の引き戻し結果を最後まで確認します。DCA成功や通常時直撃は成功回数に入れず、ボーナス本前兆との重複で後から放出される場合も区別します。',s=3)
m.pct('トランクからラブフォースワン',[16.8,17.6,21.1,23.8,25],'NORMAL_TRUNK_TRIAL','通常時のトランク成立と、その契機でCZへ当選した回数を記録します。前兆を最後まで追い、レア役や初当りの別入力と独立に重ねません。',group=g)
for state,weak,strong in [('通常',[.6,.9,2,2.7,3.1],[10.2,10.5,12.9,16,16.8]),('高確',[2.7,3.1,4.3,5.5,5.9],[25,25.8,28.9,33.2,34.8])]:
 for label,v in [('弱チェリー',weak),('強チェリー・チャンス目',strong)]:m.block(state+'の'+label+'ボーナス','成立時の内部状態を全件確定できず、通常と高確の対象役回数を正しく分けられないため使用しません。',v)
m.block('設定変更後・天国チャンス否定後モード','設定変更を確認できても通常A・B・Cを毎回直接判別できず、当選G数から推定したモード回数は使用しません。',[[71,28,1],[71,28,1],[67,32,1],[64,35,1],[62,37,1]])
m.evidence('ボーナス継続G数',{'66G':'設定6','70G':'100G完走示唆・設定の示唆ではない'},'66Gの特殊表示だけを設定条件として扱います。70Gは設定確定にしません。')
m.evidence('クリムゾングラビティ',{'単回44G':'設定4以上','単回55G':'設定5以上','単回66G':'設定6'},'1回の獲得表示に限ります。継続込みの合計が偶然44・55・66Gになっても対象外です。')
cats=['鏡','ボニー＆ニコラス','トレーニング','ブラックジャック','エリートguys','パジャマパーティー']
tables=[('0～2500G',[[92,8,0,0,0,0],[90,8,2,0,0,0],[85.5,12,2,.5,0,0],[79.3,18,2,.5,.2,0],[80.7,15,3,1,.2,.1]]),('2501～5000G',[[92,8,0,0,0,0],[90,8,2,0,0,0],[84,12,2,2,0,0],[77.5,18,2,2,.5,0],[78.2,15,3,3,.5,.3]]),('5001G以上・特殊抽選以外',[[92,8,0,0,0,0],[90,8,2,0,0,0],[84,12,2,2,0,0],[77,18,2,2,1,0],[77.5,15,3,3,1,.5]]),('7000G以上・特殊抽選1回',[[100,0,0,0,0,0],[100,0,0,0,0,0],[50,0,0,50,0,0],[50,0,0,25,25,0],[50,0,0,16.7,16.7,16.7]])]
for i,(label,rows) in enumerate(tables):
 m.num('初当りボーナス・AT終了画面・'+label,{k:dict(zip(cats,r)) for k,r in zip(['1','2','4','5','6'],rows)},'KAGAMI_END_SCREEN_TABLE_'+str(i+1)+'_TRIAL','当日総Gが分かる新しい画面抽選だけを対象とします。教会と、継続で前回と同じ示唆画面が固定再表示される回は除外します。7000G特殊抽選は最初の対象1回だけで、以後は5001G表へ戻します。表示時点のGと権利履歴が不明な回は確定条件だけ記録します。',cat=True,s=2)
m.evidence('終了画面・履歴不明時',{'鏡':'基本','ボニー＆ニコラス':'高設定示唆','トレーニング':'設定2以上','ブラックジャック':'設定4以上','エリートguys':'設定5以上','パジャマパーティー':'設定6','教会':'復活示唆・設定条件ではない'},'数値入力に使わない履歴不明の画面です。G別の数値カテゴリと同じ表示を重複登録しません。',s=2)
m.block('設定差のない小役','公開されている値は全設定共通で、設定を区別する情報ではありません。',{'弱チェリー':'1/69.8','トランク':'1/99.9','強チェリー':'1/436.9','チャンス目':'1/150.3','最強チェリー':'1/16384'})
m.block('設定Lの下パネル消灯','営業用の特殊設定を通常の推測対象に混ぜません。下パネル消灯は運用上の確認事項として保持します。')
m.notes=['原稿の7000G以上を常時別テーブルとする解釈を補正。特殊抽選は1回のみ、その後5001G表。','継続時の非デフォルト固定画面を再抽選として数えない。教会は設定のカテゴリ分布から除く。','直撃率の掲載抽選条件は通常時ハズレ。通常Gへの分母同一性を創作せず、条件付き試行として保持。']
legacy={f['featureId']:'元候補の値を保持し、通常時初当りとの包含関係、DCA失敗後、トランク試行の条件を再評価。' for f in m.baseline['features']['features']}
legacy.update({e['id']:'同じ画面の設定条件を、対象G別の数値カテゴリまたは履歴不明時の記録へ接続。' for e in m.baseline['evidence']['evidences']})
m.finish(legacy)
